import { categories } from "../../../lib/site";
import { createSupabaseServerClient } from "../../../lib/supabase/server";
import { decodeDisplayText } from "../../../lib/text";
import Link from "next/link";
import VendorTierBadge from "../../../components/VendorTierBadge";
import CategorySwitcher from "../../../components/CategorySwitcher";
import { categoryMetadata } from "../../../lib/seo";
const weight:Record<string,number>={premium:4,professional:3,pro:3,basic:2,free:1};
function photoUrl(path?:string|null){return path&&process.env.NEXT_PUBLIC_SUPABASE_URL?`${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/vendor-media/${path}`:null}
type Q={area?:string;q?:string;style?:string;price?:string;availability?:string;sort?:string;capacity?:string};
const heroCopy:Record<string,{kicker:string;headline:string;body:string}>={
 venues:{kicker:"PORTLAND WEDDING VENUES",headline:"Find a venue that feels like you.",body:"From intimate city spaces to destination-worthy Oregon settings, discover local places for the celebration you're imagining."},
 photography:{kicker:"PORTLAND WEDDING PHOTOGRAPHY",headline:"Find the person who'll capture it all.",body:"Meet local photographers whose style, perspective and storytelling fit the way you want your wedding remembered."},
 videography:{kicker:"PORTLAND WEDDING FILMS",headline:"Relive the moments you couldn't possibly catch.",body:"Discover local filmmakers who turn the movement, voices and feeling of your day into something you can keep."},
 planners:{kicker:"PORTLAND WEDDING PLANNERS",headline:"Meet the people who make everything come together.",body:"Find local planners and coordinators who can turn a hundred moving pieces into a wedding that feels effortless."},
 florists:{kicker:"PORTLAND WEDDING FLORISTS",headline:"Flowers that make the whole day feel like yours.",body:"Discover Portland floral designers for everything from wild garden romance to sculptural, modern celebrations."},
 catering:{kicker:"PORTLAND WEDDING CATERING",headline:"Make dinner one of the things they remember.",body:"Find local caterers who can build a menu around your tastes, your guests and the kind of celebration you're planning."},
 djs:{kicker:"PORTLAND WEDDING DJS",headline:"Find the one who keeps your dance floor full.",body:"Meet Portland DJs who can read the room, shape the energy and keep your celebration moving all night."},
 "hair-makeup":{kicker:"PORTLAND WEDDING BEAUTY",headline:"Look like yourself. Just on your very best day.",body:"Discover local hair and makeup artists who can create a wedding-day look that feels polished, comfortable and completely you."},
 cakes:{kicker:"PORTLAND WEDDING CAKES",headline:"Almost too beautiful to eat. Almost.",body:"Find local bakers and dessert artists creating wedding cakes and sweets that look incredible and taste even better."},
 rentals:{kicker:"PORTLAND WEDDING RENTALS",headline:"Build the setting you've been picturing.",body:"Discover local rental teams for tables, linens, lounge pieces, décor and the details that transform a space."},
 officiants:{kicker:"PORTLAND WEDDING OFFICIANTS",headline:"Find the voice for the heart of your wedding.",body:"Meet local officiants who can help create a ceremony that sounds like you and means something to the people in the room."},
 transportation:{kicker:"PORTLAND WEDDING TRANSPORTATION",headline:"Get everyone there beautifully.",body:"Find local transportation for your entrance, your wedding party and the guests who need an easy ride home."},
 stationery:{kicker:"PORTLAND WEDDING STATIONERY",headline:"Set the tone before the day even begins.",body:"Discover local designers for invitations, paper goods, signage and details that introduce your wedding beautifully."},
 bridal:{kicker:"PORTLAND BRIDAL",headline:"Find the look that makes it feel real.",body:"Explore local bridal professionals and boutiques for the pieces that make walking into your wedding feel unforgettable."},
 formalwear:{kicker:"PORTLAND WEDDING FORMALWEAR",headline:"Dress for the kind of day you're having.",body:"Find local formalwear and styling options that fit your celebration, your personality and the way you want to show up."},
 jewelry:{kicker:"PORTLAND WEDDING JEWELRY",headline:"The little things you'll keep forever.",body:"Discover local jewelers and artists for rings, wedding-day pieces and meaningful details made to last beyond the celebration."},
 "photo-booths":{kicker:"PORTLAND WEDDING PHOTO BOOTHS",headline:"Give your guests something fun to take home.",body:"Find local photo booth experiences that create instant memories, ridiculous poses and a little extra energy at the party."},
 lodging:{kicker:"PORTLAND WEDDING LODGING",headline:"Make the whole weekend feel welcoming.",body:"Discover local stays for your wedding party and guests, from convenient city hotels to memorable Oregon getaways."},
 "mobile-bars":{kicker:"PORTLAND WEDDING BARS",headline:"Raise the bar on the bar.",body:"Find local mobile bars and beverage teams for cocktails, mocktails and a guest experience worth toasting."},
 "content-creation":{kicker:"PORTLAND WEDDING CONTENT CREATORS",headline:"See your wedding again before breakfast.",body:"Meet local content creators capturing candid, behind-the-scenes moments made for sharing while the day is still fresh."},
 "live-entertainment":{kicker:"PORTLAND LIVE WEDDING ENTERTAINMENT",headline:"Give the room something to feel.",body:"Discover local musicians and performers who can make your ceremony, cocktail hour or reception come alive."},
 honeymoons:{kicker:"HONEYMOON PLANNING",headline:"Plan what happens after the last dance.",body:"Find honeymoon professionals who can help turn the trip after your wedding into an adventure worth looking forward to."}
};

export async function generateMetadata({params,searchParams}:{params:Promise<{category:string}>,searchParams:Promise<Q>}){const {category}=await params;const q=await searchParams;return categoryMetadata(category,q.area)}
export default async function CategoryPage({params,searchParams}:{params:Promise<{category:string}>,searchParams:Promise<Q>}){
 const {category}=await params; const q=await searchParams; const found=categories.find(([s])=>s===category); const title=found?.[1] || "Wedding Vendors";
 const supabase=await createSupabaseServerClient(); const {data}=await supabase.from("vendor_profiles").select("id,slug,business_name,primary_category,secondary_categories,city,state,service_cities,plan,rating,review_count,description,founding_vendor,pricing_from,pricing_typical,wedding_styles,availability_status,guest_capacity_min,guest_capacity_max,vendor_photos(storage_path,sort_order)").eq("market_slug","portland").eq("status","active").limit(250);
 let vendors=(data||[]).filter((v:any)=>v.primary_category===category||(v.secondary_categories||[]).includes(category));
 const categoryVendors=[...vendors];
 if(q.q){const needle=q.q.toLowerCase();vendors=vendors.filter((v:any)=>`${v.business_name||""} ${v.description||""}`.toLowerCase().includes(needle));}
 if(q.style)vendors=vendors.filter((v:any)=>(v.wedding_styles||[]).some((s:string)=>s.toLowerCase().includes(q.style!.toLowerCase())));
 if(q.availability==="available")vendors=vendors.filter((v:any)=>!v.availability_status||v.availability_status==="available"||v.availability_status==="accepting");
 if(q.price){const [lo,hi]=q.price.split("-").map(Number);vendors=vendors.filter((v:any)=>{const p=Number(v.pricing_from||v.pricing_typical||0);return p>0&&p>=lo&&(!hi||p<=hi)});}
 if(category==="venues"&&q.capacity){const cap=Number(q.capacity);vendors=vendors.filter((v:any)=>!v.guest_capacity_max||Number(v.guest_capacity_max)>=cap);}
 if(q.area){const area=q.area.toLowerCase();vendors=vendors.filter((v:any)=>String(v.city||"").toLowerCase()===area||(v.service_cities||[]).some((city:string)=>String(city).toLowerCase()===area));}
 vendors=vendors.sort((a:any,b:any)=>q.sort==="rating"?(b.rating||0)-(a.rating||0):q.sort==="name"?String(a.business_name).localeCompare(String(b.business_name)):(Number(b.founding_vendor)-Number(a.founding_vendor))||(weight[String(b.plan||"").toLowerCase()]||0)-(weight[String(a.plan||"").toLowerCase()]||0)||(b.rating||0)-(a.rating||0));
 const styles=Array.from(new Set(categoryVendors.flatMap((v:any)=>(v.wedding_styles||[]).map((s:string)=>decodeDisplayText(s))))).sort().slice(0,30); const serviceAreas=Array.from(new Set(categoryVendors.flatMap((v:any)=>[v.city,...(v.service_cities||[])]).filter(Boolean).map((city:any)=>decodeDisplayText(String(city))))).sort().slice(0,60);
 const hero=heroCopy[category]||{kicker:`PORTLAND WEDDING ${title.toUpperCase()}`,headline:`Find ${title.toLowerCase()} that feel like you.`,body:`Discover local ${title.toLowerCase()} and find the people who fit your wedding, your priorities and your plans.`};
 // Stable daily hero rotation: prioritize paid exposure tiers while rotating fairly within the highest eligible tier.
 const imageCandidates=categoryVendors.filter((v:any)=>(v.vendor_photos||[]).some((p:any)=>Boolean(String(p?.storage_path||"").trim())));
 const paidImageCandidates=imageCandidates.filter((v:any)=>String(v.plan||"").toLowerCase()!=="free");
 const heroCandidates=paidImageCandidates;
 const heroPriority=(v:any)=>v.founding_vendor?5:(weight[String(v.plan||"").toLowerCase()]||0);
 const highestHeroPriority=heroCandidates.reduce((max:number,v:any)=>Math.max(max,heroPriority(v)),0);
 const heroPool=heroCandidates.filter((v:any)=>heroPriority(v)===highestHeroPriority).sort((a:any,b:any)=>String(a.id).localeCompare(String(b.id)));
 const dayNumber=Math.floor(Date.now()/86400000);
 const categorySeed=Array.from(category).reduce((sum,ch)=>sum+ch.charCodeAt(0),0);
 const heroVendor=heroPool.length?heroPool[(dayNumber+categorySeed)%heroPool.length]:undefined;
 const heroPhotos=(heroVendor?.vendor_photos||[]).sort((a:any,b:any)=>(a.sort_order||0)-(b.sort_order||0));
 const heroSrc=photoUrl(heroPhotos[0]?.storage_path);
 const heroVendorName=heroVendor ? decodeDisplayText(heroVendor.business_name) : "";
 return <main><section className="vendorEditorialHero"><div className="container vendorEditorialHeroInner"><div className="vendorEditorialCopy"><span className="vendorHeroKicker">{hero.kicker}</span><h1>{hero.headline} <span className="vendorHeroHeart">♡</span></h1><p>{hero.body}</p><div className="vendorHeroDetails"><span><strong>{categoryVendors.length}</strong> local {title.toLowerCase()}</span><span>♡ Save the ones you love</span></div></div><div className={`vendorHeroVisual ${heroSrc?"hasPhoto":"vendorImageFallback"}`}>{heroSrc&&heroVendor?<Link className="vendorHeroProfileLink" href={`/vendor/${heroVendor.slug}`} aria-label={`View ${heroVendorName} profile`}><img className="vendorHeroBackdrop" src={heroSrc} alt="" aria-hidden="true"/><img className="vendorHeroImage" src={heroSrc} alt={heroVendorName ? `${heroVendorName} wedding work` : "Wedding vendor work"}/><span className="vendorHeroCredit">Featured: {heroVendorName} · View Profile →</span></Link>:<div className="mpwVendorImageFallback"><img src="/brand/mpw-heart-sprig-clean.png" alt="My Portland Wedding"/><span>{title}</span><small>Portland, Oregon</small></div>}</div></div></section><section className="section vendorMarketplaceSection"><div className="container"><div className="categoryToolbar"><CategorySwitcher currentCategory={category}/></div><form className="vendorFilterBar" action={`/vendors/${category}`}><label className="vendorFilter searchFilter"><span>⌕</span><input name="q" defaultValue={q.q||""} placeholder={`Search ${title.toLowerCase()}…`}/></label><label className="vendorFilter"><select name="area" defaultValue={q.area||""}><option value="">Service Area</option>{serviceAreas.map(area=><option key={area} value={area}>{area}</option>)}</select></label><label className="vendorFilter"><select name="style" defaultValue={q.style||""}><option value="">All Styles</option>{styles.map(style=><option key={style} value={style}>{style}</option>)}</select></label><label className="vendorFilter"><select name="price" defaultValue={q.price||""}><option value="">Price Range</option><option value="0-1000">Under $1,000</option><option value="1000-2500">$1,000–$2,500</option><option value="2500-5000">$2,500–$5,000</option><option value="5000-10000">$5,000–$10,000</option><option value="10000-0">$10,000+</option></select></label>{category==="venues"?<label className="vendorFilter"><select name="capacity" defaultValue={q.capacity||""}><option value="">Guest Capacity</option><option value="50">50+ guests</option><option value="100">100+ guests</option><option value="150">150+ guests</option><option value="200">200+ guests</option></select></label>:<label className="vendorFilter"><select name="availability" defaultValue={q.availability||""}><option value="">Availability</option><option value="available">Accepting weddings</option></select></label>}<label className="vendorFilter"><span>⇅</span><select name="sort" defaultValue={q.sort||""}><option value="">Recommended</option><option value="rating">Top Rated</option><option value="name">A–Z</option></select></label><button className="vendorFilterApply">Apply</button></form><div className="vendorResultsHead"><p><strong>{vendors.length}</strong> {title} found</p>{(q.q||q.area||q.style||q.price||q.availability||q.sort||q.capacity)&&<Link href={`/vendors/${category}`}>Clear filters ×</Link>}</div>{vendors.length?<div className="vendorMarketplaceGrid">{vendors.map((v:any)=>{const photos=(v.vendor_photos||[]).sort((a:any,b:any)=>(a.sort_order||0)-(b.sort_order||0));const src=photoUrl(photos[0]?.storage_path);return <Link href={`/vendor/${v.slug}`} className="marketVendorCard" key={v.id}><div className={`marketVendorPhoto ${src?"hasVendorPhoto":"vendorImageFallback"}`}>{src?<><img className="marketVendorBackdrop" src={src} alt="" aria-hidden="true"/><img className="marketVendorForeground" src={src} alt={`${decodeDisplayText(v.business_name)} wedding work`}/></>:<div className="mpwVendorImageFallback compact"><img src="/brand/mpw-heart-sprig-clean.png" alt=""/><span>{title}</span></div>}<div className="marketVendorBadge"><VendorTierBadge plan={v.plan} foundingVendor={v.founding_vendor}/></div></div><div className="marketVendorBody"><h3>{decodeDisplayText(v.business_name)}</h3><p className="marketVendorMeta">{decodeDisplayText(v.city||"Portland")}, {v.state||"OR"}{v.rating?` · ★ ${v.rating}`:""}</p><p className="marketVendorBio">{decodeDisplayText(v.description||"View profile, services and contact information.")}</p><span className="vendorCardCta">View Profile →</span></div></Link>})}</div>:<div className="emptyState"><h3>No {title.toLowerCase()} matched those filters yet.</h3><p className="meta">Try widening your filters or browse all local {title.toLowerCase()}.</p><Link className="btn primary" href={`/vendors/${category}`}>Clear Filters</Link></div>}</div></section></main>
}
